function rampartSimulate(createStrategy, seed, maxTicks) {
  const record = arguments[3];
  const ground = [[0,2],[6,2],[6,10],[12,10],[12,3],[18,3],[18,11],[23,11]];
  const air = [[0,6],[21,6],[21,11],[23,11]];
  const slots = [[3,3],[5,5],[7,4],[7,8],[9,9],[10,5],[11,8],[13,8],
    [14,5],[15,2],[16,7],[17,4],[19,8],[20,10],[22,9],[3,7]]
    .map(([x,y], slot) => ({slot,x,y,turret:null}));
  const types = ['"'bolt','cannon','frost','lance','flak'];
  const specs = [
    [50,26,8,300,0,0,false,3], [90,60,24,260,90,0,false,1],
    [70,10,12,240,0,30,false,3], [120,180,36,360,0,0,true,1],
    [80,40,10,320,70,0,false,2]
  ];
  const breeds = [
    ['grunt',60,10,4,1,0,1,10], ['runner',40,20,4,1,0,2,4],
    ['wisp',50,12,6,2,1,3,3], ['brute',150,6,9,3,0,4,3],
    ['splitter',90,8,6,2,0,6,2], ['mender',70,8,7,2,0,8,1],
    ['splitling',0,12,1,1,0,Infinity,0]
  ];
  function mulberry32(a) { return function () {
    a = (a + 0x6D2B79F5) | 0; let t = Math.imul(a "'^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ''^ (t >>> 7), 61 | t)) ''^ t; return (t ''^ (t >>> 14)) >>> 0; }; }
  const draw = mulberry32(seed);
  const strategy = createStrategy(), log = [];
  const enemies = [], queue = new Map(), multipliers = [0,1000];
  let wave = 0, gold = 250, baseHp = 10, lastId = 0, fallTick = -1;
  let next = generate(1), tick, events;
  function generate(w) {
    const available = breeds.filter(b => b[6] <= w);
    const weight = available.reduce((sum,b) => sum + b[7],0);
    return Array.from({length:4 + Math.floor(3*w/5)}, () => {
      let roll = draw() % weight;
      return available.find(b => (roll -= b[7]) < 0);
    });
  }
  function position(e) {
    const route = e.air ? air : ground;
    let p = e.progress;
    for (let i=1;i<route.length;i++) {
      const [x,y] = route[i-1], [nx,ny] = route[i];
      const dx = Math.sign(nx-x), dy = Math.sign(ny-y);
      const span = 100*(Math.abs(nx-x)+Math.abs(ny-y));
      if (p < span || i === route.length-1) {
        e.x = 100*x+50+dx*p; e.y = 100*y+50+dy*p;
        e.remaining = (e.air ? 2600 : 4600)-e.progress;
        e.heading = Math.atan2(dx,dy);
        return;
      }
      p -= span;
    }
  }
  function spawn(b,w,progress=0,childHp) {
    const [type,hp,speed,bounty,leak,airborne] = b;
    const maxHp = childHp ?? Math.floor(hp*multipliers[w]/1000);
    const armor = type === '"'grunt' ? Math.floor(w/4) : type === 'brute' ? 6+w : 0;
    const enemy = {id:++lastId,type,hp:maxHp,maxHp,x:0,y:0,air:airborne,armor,speed,
      slow:0,remaining:0,progress,w,bounty,leak,age:0};
    position(enemy);
    enemies.push(enemy);
    return enemy;
  }
  function view(e) {
    const {id,type,hp,maxHp,x,y,air,armor,speed,remaining} = e;
    return {id,type,hp,maxHp,x,y,air,armor,speed,slowed:e.slow>0,remaining};
  }
  function turretView(t) {
    const {type,tier,spent} = t;
    return {type,tier,spent};
  }
  function detail(kind, data) {
    if (record) events.push({kind,...data});
  }
  function apply(action) {
    if ("'!action || !Number.isInteger(action.slot)) return;
    const sl = slots[action.slot];
    if (!sl) return;
    const t = sl.turret;
    if (action.op === '"'build' && "'!t) {
      const index = types.indexOf(action.type);
      if (index < 0) return;
      const [cost,damage,period,range,splash,slow,pierce,domain] = specs[index];
      if (gold < cost) return;
      gold -= cost;
      sl.turret = {type:types[index],tier:1,spent:cost,cost,damage,period,range,splash,slow,pierce,domain,cooldown:0};
      log.push([tick,'"'B',sl.slot,index]);
      detail('build',{x:100*sl.x+50,y:100*sl.y+50,type:types[index]});
    } else if (action.op === 'upgrade' && t && t.tier < 3 && gold >= t.cost*t.tier) {
      const cost = t.cost*t.tier;
      gold -= cost;
      t.spent += cost; t.tier++; t.damage = Math.floor(t.damage*16/10); t.range += 30;
      log.push([tick,'U',sl.slot,t.tier]);
      detail('upgrade',{x:100*sl.x+50,y:100*sl.y+50,type:t.type});
    } else if (action.op === 'sell' && t) {
      gold += Math.floor(t.spent*70/100);
      sl.turret = null;
      log.push([tick,'S',sl.slot,0]);
      detail('sell',{x:100*sl.x+50,y:100*sl.y+50,type:t.type});
    }
  }
  function near(x,y,e,r) {
    const dx = x-e.x, dy = y-e.y;
    return dx*dx+dy*dy <= r*r;
  }
  function snapshot() {
    if (record) record(tick, {wave,gold,baseHp,events,nextWave:next.map(b=>b[0]),
      turrets:slots.map(s=>s.turret ? turretView(s.turret) : null),
      enemies:enemies.map(e=>({...view(e),heading:e.heading}))});
  }
  for (tick=0;tick<maxTicks;tick++) {
    if (record) events = [];
    if (tick >= 20 && (tick-20)%40 === 0) {
      wave++;
      if (wave > 1) multipliers[wave] = Math.floor(multipliers[wave-1]*108/100);
      gold += Math.min(50,Math.floor(gold*5/100))+10+2*wave;
      const current = next;
      next = generate(wave+1);
      detail('wave',{x:50,y:250});
      const actions = strategy.plan({tick,wave,gold,baseHp,
        slots:slots.map(s=>({...s,turret:s.turret ? turretView(s.turret) : null})),
        enemies:enemies.map(view),nextWave:next.map(b=>b[0])});
      if (Array.isArray(actions)) for (const a of actions.slice(0,32)) apply(a);
      current.forEach((b,i)=>{
        const due = tick+4*i;
        if ("'!queue.has(due)) queue.set(due,[]);
        queue.get(due).push([b,wave]);
      });
    }
    const due = queue.get(tick);
    if (due) {
      for (const [breed,w] of due) spawn(breed,w);
      queue.delete(tick);
    }
    for (let i=0;i<enemies.length;) {
      const e = enemies[i];
      e.progress += e.slow > 0 ? Math.floor(e.speed*60/100) : e.speed;
      if (e.progress >= (e.air ? 2600 : 4600)) {
        enemies.splice(i,1);
        baseHp -= e.leak;
        log.push([tick,'"'L',e.id,baseHp]);
        detail('leak',{x:2350,y:1150,hp:baseHp,damage:e.leak});
        if (baseHp <= 0) {
          fallTick = tick;
          log.push([tick,'F',wave,0]);
          detail('fall',{x:2350,y:1150});
          break;
        }
      } else {
        position(e);
        i++;
      }
    }
    if (fallTick "'!== -1) { snapshot(); break; }
    for (const e of enemies) {
      e.age++;
      if (e.type === '"'mender' && e.age%20 === 0) {
        for (const other of enemies) if (near(e.x,e.y,other,150)) {
          other.hp = Math.min(other.maxHp,other.hp+Math.floor(other.maxHp*8/100));
        }
        detail('heal',{x:e.x,y:e.y});
      }
    }
    for (const sl of slots) {
      const t = sl.turret;
      if ("'!t || (t.cooldown > 0 && --t.cooldown > 0)) continue;
      const x = 100*sl.x+50, y = 100*sl.y+50;
      const candidates = enemies.filter(e=>(t.domain & (1<<e.air)) && near(x,y,e,t.range));
      if (!candidates.length) continue;
      const id = strategy.target?.({slot:sl.slot,type:t.type,tier:t.tier,x,y,range:t.range},candidates.map(view));
      const target = candidates.find(e=>e.id===id) ??
        candidates.reduce((best,e)=>e.remaining < best.remaining ? e : best);
      const hit = t.splash ? enemies.filter(e=>(t.domain & (1<<e.air)) && near(target.x,target.y,e,t.splash)) : [target];
      for (const e of hit) {
        e.hp -= Math.max(1,t.damage-(t.pierce ? 0 : e.armor));
        if (t.slow) e.slow = t.slow;
      }
      t.cooldown = t.period;
      detail('"'shot',{x,y,tx:target.x,ty:target.y,air:target.air,type:t.type,slot:sl.slot});
      for (let i=0;i<enemies.length;) {
        const e = enemies[i];
        if (e.hp > 0) { i++; continue; }
        enemies.splice(i,1);
        gold += e.bounty;
        log.push([tick,'K',e.id,sl.slot]);
        detail('kill',{x:e.x,y:e.y,air:e.air,type:e.type});
        if (e.type === 'splitter') {
          const hp = Math.max(1,Math.floor(e.maxHp/4));
          for (let j=0;j<3;j++) spawn(breeds[6],e.w,e.progress,hp);
        }
      }
    }
    for (const e of enemies) if (e.slow > 0) e.slow--;
    snapshot();
  }
